// src/processor.mjs
// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._bufferedIds = new Set(); // ids in buffer
    this._appliedIds = new Set(); // ids already applied
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Defensive: ignore malformed
    if (!event || typeof event.id !== 'string' || typeof event.seq !== 'number') {
      return [];
    }

    // Idempotent: already applied
    if (this._appliedIds.has(event.id)) {
      return [];
    }
    // Idempotent: already buffered
    if (this._bufferedIds.has(event.id)) {
      return [];
    }
    // Stale seq already applied
    if (event.seq <= this.lastSeq) {
      return [];
    }
    // Duplicate seq already buffered (different id) -> keep first
    if (this._buffer.has(event.seq)) {
      return [];
    }

    // Buffer it
    this._buffer.set(event.seq, event);
    this._bufferedIds.add(event.id);

    const applied = [];

    // Drain in order
    while (true) {
      const nextSeq = this.lastSeq + 1;
      const nextEvent = this._buffer.get(nextSeq);
      if (!nextEvent) break;

      // Remove before apply to avoid double-apply on re-entrancy
      this._buffer.delete(nextSeq);
      this._bufferedIds.delete(nextEvent.id);

      try {
        const maybePromise = this.apply(nextEvent);

        // If apply returns a thenable, avoid unhandled rejection; still treat as applied
        if (maybePromise && typeof maybePromise.then === 'function') {
          // Attach catch for cleanup of async rejection (no await, interface is sync)
          maybePromise.catch(() => {});
        }

        this._appliedIds.add(nextEvent.id);
        this.lastSeq = nextSeq;
        applied.push(nextEvent);
      } catch (err) {
        // Rollback: restore buffer state, do not advance lastSeq nor mark applied
        this._buffer.set(nextSeq, nextEvent);
        this._bufferedIds.add(nextEvent.id);
        throw err;
      }
    }

    return applied;
  }
}
